public void runTask() {
    try {
        while (!Thread.currentThread().isInterrupted()) {
            // Perform work
            Thread.sleep(1000);
        }
    } catch (InterruptedException e) {
        // Restore the interrupted status so callers know it happened
        Thread.currentThread().interrupt();
        // Perform cleanup here
        System.err.println("Task interrupted, cleaning up...");
    }
}
